// ─── Watermark component reutilizable ───────────────────────────────────────
function WatermarkBackground() {
  if (typeof document === "undefined") return null;
  return React.createElement("div", {
    dangerouslySetInnerHTML: { __html: WATERMARK_SVG },
    style: {
      position: "absolute",
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      width: "100%",
      height: "100%",
      opacity: 0.05,
      pointerEvents: "none",
      overflow: "hidden",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      zIndex: 0,
    },
  });
}

// ─────────────────────────────────────────────
// RESPONSIVE HOOK
// ─────────────────────────────────────────────
function useLayout() {
  const { width, height } = useWindowDimensions();
  const isSmall = height < 680;
  const timerSize = Math.min(width * 0.6, height * 0.3);
  return { width, height, isSmall, timerSize };
}

// ─────────────────────────────────────────────
// AUDIO
// ─────────────────────────────────────────────
const audioCtx = (() => {
  try {
    const C = window.AudioContext || window.webkitAudioContext;
    return C ? new C() : null;
  } catch {
    return null;
  }
})();

function tone(freqs = [880], dur = 0.12, vol = 0.4, type = "sine") {
  if (!audioCtx) return;
  if (audioCtx.state === "suspended") audioCtx.resume();
  let t = audioCtx.currentTime;
  freqs.forEach((f) => {
    const osc = audioCtx.createOscillator(),
      g = audioCtx.createGain();
    osc.connect(g);
    g.connect(audioCtx.destination);
    osc.type = type;
    osc.frequency.setValueAtTime(f, t);
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(vol, t + 0.01);
    g.gain.linearRampToValueAtTime(0, t + dur - 0.01);
    osc.start(t);
    osc.stop(t + dur);
    t += dur + 0.04;
  });
}
const beepCorto = () => tone([880], 0.1, 0.35);
const beepLargo = () => tone([523, 659, 784], 0.18, 0.4);
const beepFinal = () => tone([523, 659, 784, 1047], 0.2, 0.45);

