// ─────────────────────────────────────────────
// HOOKS DE DATOS
// ─────────────────────────────────────────────
function useHistorial() {
  const [historial, setHistorial] = useState({});
  useEffect(() => {
    AsyncStorage.getItem("@hist_v10")
      .then((h) => {
        if (h) setHistorial(JSON.parse(h));
      })
      .catch(() => {});
  }, []);
  const registrar = useCallback((minutos = 0) => {
    const hoy = new Date().toISOString().split("T")[0];
    setHistorial((prev) => {
      const e = prev[hoy] || { sesiones: 0, minutos: 0 };
      const next = {
        ...prev,
        [hoy]: { sesiones: e.sesiones + 1, minutos: e.minutos + minutos },
      };
      AsyncStorage.setItem("@hist_v10", JSON.stringify(next)).catch(() => {});
      return next;
    });
  }, []);
  const racha = useCallback(() => {
    const dias = Object.keys(historial).sort().reverse();
    if (!dias.length) return 0;
    let r = 0;
    let c = new Date();
    c.setHours(0, 0, 0, 0);
    for (const d of dias) {
      const f = new Date(d + "T00:00:00");
      if ((c - f) / 86400000 > 1) break;
      r++;
      c = f;
    }
    return r;
  }, [historial]);
  const totalSesiones = Object.values(historial).reduce(
    (a, d) => a + (d.sesiones || 0),
    0
  );
  const totalMinutos = Object.values(historial).reduce(
    (a, d) => a + (d.minutos || 0),
    0
  );
  return { historial, registrar, racha, totalSesiones, totalMinutos };
}

function useFavoritos() {
  const [favoritos, setFavoritos] = useState([]);
  useEffect(() => {
    AsyncStorage.getItem("@favs_v2")
      .then((f) => {
        if (f) setFavoritos(JSON.parse(f));
      })
      .catch(() => {});
  }, []);
  const guardar = useCallback((nombre, config, emoji = "⭐") => {
    setFavoritos((prev) => {
      const next = [
        { id: Date.now().toString(), nombre, config, emoji },
        ...prev,
      ];
      AsyncStorage.setItem("@favs_v2", JSON.stringify(next)).catch(() => {});
      return next;
    });
  }, []);
  const eliminar = useCallback((id) => {
    setFavoritos((prev) => {
      const next = prev.filter((f) => f.id !== id);
      AsyncStorage.setItem("@favs_v2", JSON.stringify(next)).catch(() => {});
      return next;
    });
  }, []);
  return { favoritos, guardar, eliminar };
}

// ─────────────────────────────────────────────
// CircularTimer
// ─────────────────────────────────────────────
function CircularTimer({
  fase,
  tiempo,
  progreso,
  activo,
  pausado,
  size,
  estacionIdx,
  totalEstaciones,
}) {
  const { timerSize } = useLayout();
  const pulse = useRef(new Animated.Value(1)).current;
  const color = ACCENT[fase] || "#fff";
  const S = size ?? timerSize;

  useEffect(() => {
    if (activo && !pausado) {
      const loop = Animated.loop(
        Animated.sequence([
          Animated.timing(pulse, {
            toValue: 1.04,
            duration: 900,
            useNativeDriver: true,
          }),
          Animated.timing(pulse, {
            toValue: 1,
            duration: 900,
            useNativeDriver: true,
          }),
        ])
      );
      loop.start();
      return () => loop.stop();
    }
    Animated.timing(pulse, {
      toValue: 1,
      duration: 200,
      useNativeDriver: true,
    }).start();
  }, [activo, pausado]);

  return (
    <Animated.View
      style={{
        width: S,
        height: S,
        borderRadius: S / 2,
        borderColor: color,
        borderWidth: 4,
        justifyContent: "center",
        alignItems: "center",
        backgroundColor: "rgba(0,0,0,0.25)",
        transform: [{ scale: pulse }],
        shadowColor: color,
        shadowOpacity: 0.6,
        shadowRadius: 20,
        shadowOffset: { width: 0, height: 0 },
        elevation: 12,
      }}
    >
      <View
        style={{
          position: "absolute",
          width: S * 0.88,
          height: S * 0.88,
          borderRadius: S / 2,
          borderColor: `${color}22`,
          borderWidth: 8,
        }}
      />
      <Text
        style={{
          color,
          fontSize: tiempo.length > 4 ? S * 0.18 : S * 0.25,
          fontWeight: "900",
          letterSpacing: -2,
        }}
      >
        {tiempo}
      </Text>
      {(fase === "TRABAJO" || fase === "DESCANSO") && totalEstaciones > 1 && (
        <View style={{ flexDirection: "row", gap: 5, marginTop: 6 }}>
          {Array.from({ length: totalEstaciones }).map((_, i) => (
            <View
              key={i}
              style={{
                width: 6,
                height: 6,
                borderRadius: 3,
                backgroundColor: i === estacionIdx ? color : `${color}44`,
              }}
            />
          ))}
        </View>
      )}
      {pausado && (
        <Text
          style={{
            color: "rgba(255,255,255,0.4)",
            fontSize: 9,
            letterSpacing: 3,
            marginTop: 4,
          }}
        >
          PAUSADO
        </Text>
      )}
      <View
        style={{
          position: "absolute",
          bottom: 10,
          right: 10,
          paddingHorizontal: 7,
          paddingVertical: 3,
          borderRadius: 9,
          backgroundColor: color + "33",
          borderColor: color + "66",
          borderWidth: 1,
        }}
      >
        <Text style={{ color, fontSize: 9, fontWeight: "800" }}>
          {Math.round(progreso * 100)}%
        </Text>
      </View>
    </Animated.View>
  );
}

