// ─────────────────────────────────────────────
// APP
// ─────────────────────────────────────────────
export default function App() {
  const hist = useHistorial();
  const { favoritos, guardar, eliminar } = useFavoritos();
  const { isSmall } = useLayout();

  const [config, setConfig] = useState(DEFAULT_CONFIG);

  const [fase, setFase] = useState("CALENTAMIENTO");
  const [segundos, setSegundos] = useState(DEFAULT_CONFIG.cal * 60);
  const [activo, setActivo] = useState(false);
  const [pausado, setPausado] = useState(false);
  const [ronda, setRonda] = useState(1);
  const [estacionIdx, setEstacionIdx] = useState(0);
  const [terminado, setTerminado] = useState(false);
  const [progreso, setProgreso] = useState(0);
  const [esOscuro, setEsOscuro] = useState(true);
  const [showGen, setShowGen] = useState(false);
  const [showSave, setShowSave] = useState(false);
  const [activeTab, setActiveTab] = useState("timer");

  const cfgRef = useRef(config);
  const faseRef = useRef(fase);
  const rondaRef = useRef(ronda);
  const estacionIdxRef = useRef(estacionIdx);
  useEffect(() => {
    cfgRef.current = config;
  }, [config]);
  useEffect(() => {
    faseRef.current = fase;
  }, [fase]);
  useEffect(() => {
    rondaRef.current = ronda;
  }, [ronda]);
  useEffect(() => {
    estacionIdxRef.current = estacionIdx;
  }, [estacionIdx]);

  const durTotal = useCallback(() => calcDurTotal(cfgRef.current), []);

  const alertar = useCallback((tipo) => {
    if (tipo === "corto") {
      Vibration.vibrate(80);
      beepCorto();
    } else if (tipo === "final") {
      Vibration.vibrate([0, 300, 100, 300, 100, 300]);
      beepFinal();
    } else {
      Vibration.vibrate([0, 200, 80, 200]);
      beepLargo();
    }
  }, []);

  const siguienteFase = useCallback(() => {
    const f = faseRef.current;
    const c = cfgRef.current;
    const r = rondaRef.current;
    const idx = estacionIdxRef.current;
    const numEst = c.estaciones.length;

    if (f === "CALENTAMIENTO") {
      setFase("PREPARACIÓN");
      setSegundos(c.prep);
    } else if (f === "PREPARACIÓN") {
      setEstacionIdx(0);
      setFase("TRABAJO");
      setSegundos(c.estaciones[0].trabajo);
    } else if (f === "TRABAJO") {
      setFase("DESCANSO");
      setSegundos(c.estaciones[idx].descanso);
    } else if (f === "DESCANSO") {
      const nextIdx = idx + 1;
      if (nextIdx < numEst) {
        setEstacionIdx(nextIdx);
        setFase("TRABAJO");
        setSegundos(c.estaciones[nextIdx].trabajo);
      } else {
        if (r < c.rondas) {
          setRonda((p) => p + 1);
          setEstacionIdx(0);
          setFase("TRABAJO");
          setSegundos(c.estaciones[0].trabajo);
        } else {
          setActivo(false);
          setTerminado(true);
          setProgreso(1);
          alertar("final");
        }
      }
    }
  }, [alertar]);

  useEffect(() => {
    if (!activo || pausado) return;
    const total = durTotal();
    const int = setInterval(() => {
      setSegundos((s) => {
        if (s <= 4 && s > 1) alertar("corto");
        if (s <= 1) {
          alertar("largo");
          setTimeout(siguienteFase, 0);
          return 0;
        }
        return s - 1;
      });
      setProgreso((p) => Math.min(p + 1 / total, 1));
    }, 1000);
    return () => clearInterval(int);
  }, [activo, pausado, alertar, siguienteFase, durTotal]);

  useEffect(() => {
    if (terminado) hist.registrar(Math.round(durTotal() / 60));
  }, [terminado]);

  const formatTiempo = () => {
    if (fase === "CALENTAMIENTO") {
      const m = Math.floor(segundos / 60);
      return `${m}:${(segundos % 60).toString().padStart(2, "0")}`;
    }
    return String(segundos);
  };

  const iniciar = () => {
    if (audioCtx?.state === "suspended") audioCtx.resume();
    setTerminado(false);
    setActivo(true);
    setPausado(false);
    setProgreso(0);
    setActiveTab("timer");
  };
  const pausar = () => setPausado((p) => !p);
  const reset = () => {
    setActivo(false);
    setPausado(false);
    setTerminado(false);
    setFase("CALENTAMIENTO");
    setSegundos(cfgRef.current.cal * 60);
    setRonda(1);
    setEstacionIdx(0);
    setProgreso(0);
  };

  const aplicarConfig = (cfg) => {
    setConfig(cfg);
    cfgRef.current = cfg;
    setFase("CALENTAMIENTO");
    setSegundos(cfg.cal * 60);
    setRonda(1);
    setEstacionIdx(0);
    setActivo(false);
    setPausado(false);
    setTerminado(false);
    setProgreso(0);
    setActiveTab("timer");
  };
  const aplicarPreset = (key) => aplicarConfig(PRESETS[key]);

  const actualizarConfig = (key, valor) => {
    const val = Math.max(1, valor);
    setConfig((prev) => {
      const next = { ...prev, [key]: val };
      cfgRef.current = next;
      return next;
    });
    if (key === "cal") setSegundos(Math.max(1, valor) * 60);
  };

  const actualizarEstacion = (index, field, value) => {
    const val = Math.max(5, value);
    setConfig((prev) => {
      const estaciones = prev.estaciones.map((e, i) =>
        i === index ? { ...e, [field]: val } : e
      );
      const next = { ...prev, estaciones };
      cfgRef.current = next;
      return next;
    });
  };

  const addEstacion = () => {
    setConfig((prev) => {
      const next = {
        ...prev,
        estaciones: [...prev.estaciones, { ...DEFAULT_ESTACION }],
      };
      cfgRef.current = next;
      return next;
    });
  };

  const removeEstacion = (index) => {
    setConfig((prev) => {
      if (prev.estaciones.length <= 1) return prev;
      const estaciones = prev.estaciones.filter((_, i) => i !== index);
      const next = { ...prev, estaciones };
      cfgRef.current = next;
      return next;
    });
  };

  const bgMap = esOscuro ? BG_DARK : BG_LIGHT;
  const bgColor = bgMap[fase] || "#0d2b45";
  const tabLabel =
    TABS.find((t) => t.key === activeTab)?.label.toUpperCase() || "";

  const renderContent = () => {
    switch (activeTab) {
      case "timer":
        return (
          <TimerScreen
            fase={fase}
            ronda={ronda}
            estacionIdx={estacionIdx}
            config={config}
            tiempo={formatTiempo()}
            progreso={progreso}
            activo={activo}
            pausado={pausado}
            onIniciar={iniciar}
            onPausar={pausar}
            onReset={reset}
          />
        );
      case "config":
        return (
          <ConfigScreen
            config={config}
            onUpdate={actualizarConfig}
            onUpdateEstacion={actualizarEstacion}
            onAddEstacion={addEstacion}
            onRemoveEstacion={removeEstacion}
            onPreset={aplicarPreset}
            onGuardar={() => setShowSave(true)}
            onGenerador={() => setShowGen(true)}
          />
        );
      case "favoritos":
        return (
          <FavoritosScreen
            favoritos={favoritos}
            eliminar={eliminar}
            onCargar={aplicarConfig}
          />
        );
      case "historial":
        return (
          <HistorialScreen
            historial={hist.historial}
            racha={hist.racha()}
            totalSesiones={hist.totalSesiones}
            totalMinutos={hist.totalMinutos}
          />
        );
    }
  };

  const NAV_H = isSmall ? 54 : 66;

  return (
    <View
      style={{
        flex: 1,
        minHeight: "100vh",
        backgroundColor: bgColor,
        position: "relative",
      }}
    >
      {/* Marca de agua global (capa de fondo general) */}
      <WatermarkBackground />

      <StatusBar barStyle="light-content" backgroundColor={bgColor} />
      <SafeAreaView style={{ flex: 1, height: "100%", position: "relative" }}>
        {/* HEADER */}
        <View
          style={{
            flexDirection: "row",
            justifyContent: "space-between",
            alignItems: "center",
            paddingHorizontal: 24,
            paddingVertical: isSmall ? 8 : 12,
            zIndex: 1,
          }}
        >
          <View>
            <Text
              style={{
                color: "rgba(255,255,255,0.3)",
                fontSize: 10,
                fontWeight: "800",
                letterSpacing: 4,
                marginBottom: 2,
              }}
            >
              INTERVAL
            </Text>
            <Text
              style={{
                color: "white",
                fontSize: isSmall ? 15 : 19,
                fontWeight: "300",
                letterSpacing: 4,
              }}
            >
              {activeTab === "timer"
                ? `${fase}${
                    fase === "TRABAJO" || fase === "DESCANSO"
                      ? `  ${ronda}/${config.rondas}  ·  ${estacionIdx + 1}/${
                          config.estaciones.length
                        }`
                      : ""
                  }`
                : tabLabel}
            </Text>
          </View>
          <TouchableOpacity
            onPress={() => setEsOscuro(!esOscuro)}
            style={{
              width: 40,
              height: 40,
              borderRadius: 20,
              backgroundColor: "rgba(255,255,255,0.12)",
              justifyContent: "center",
              alignItems: "center",
            }}
          >
            <Text style={{ fontSize: 20 }}>{esOscuro ? "☀️" : "🌙"}</Text>
          </TouchableOpacity>
        </View>

        {/* CONTENT */}
        <View style={{ flex: 1, paddingBottom: NAV_H, zIndex: 1 }}>
          {renderContent()}
        </View>

        {/* NAVBAR */}
        <View
          style={{
            position: "absolute",
            bottom: 0,
            left: 0,
            right: 0,
            zIndex: 100,
          }}
        >
          <NavBar
            active={activeTab}
            onPress={setActiveTab}
            bg={bgColor}
            favsCount={favoritos.length}
            timerActivo={activo}
          />
        </View>
      </SafeAreaView>

      <GeneradorModal
        visible={showGen}
        onAplicar={aplicarConfig}
        onClose={() => setShowGen(false)}
      />
      <GuardarModal
        visible={showSave}
        config={config}
        onGuardar={(n, e) => guardar(n, config, e)}
        onClose={() => setShowSave(false)}
      />
      <ResumenModal
        visible={terminado}
        config={config}
        racha={hist.racha()}
        totalSesiones={hist.totalSesiones}
        onClose={reset}
      />
    </View>
  );
}

const s = StyleSheet.create({
  label: {
    color: "rgba(255,255,255,0.3)",
    fontSize: 9,
    fontWeight: "800",
    letterSpacing: 3,
    marginBottom: 10,
  },
  labelModal: {
    color: "rgba(255,255,255,0.4)",
    fontSize: 9,
    letterSpacing: 3,
    marginBottom: 10,
  },
});
